        &lt;PAP_InternalIdentifier&gt;Button.Add.CreateEntity&lt;/PAP_InternalIdentifier&gt;
        &lt;EntityIdentifier&gt;8ca2a9b1-4331-46a5-8f48-691c4a79a1c7&lt;/EntityIdentifier&gt;
        &lt;IsUidEnabled&gt;True&lt;/IsUidEnabled&gt;
      &lt;/Metadata&gt;
      &lt;OrderIndex&gt;4&lt;/OrderIndex&gt;
      &lt;ActionType&gt;PlantAnApp.CreateEntity.8ca2a9b1-4331-46a5-8f48-691c4a79a1c7&lt;/ActionType&gt;
      &lt;ActionData&gt;{&quot;OutputToken&quot;:&quot;NewPersoanaIntretinereId&quot;,&quot;CodSucursala&quot;:&quot;[p_CodSucursala]&quot;,&quot;Marca&quot;:&quot;[p_Marca]&quot;,&quot;CNPAltaPersoana&quot;:&quot;[p_CNPAltaPersoana]&quot;,&quot;PrenumeAltaPersoana&quot;:&quot;[p_PrenumeAltaPersoana]&quot;,&quot;FelPersoana&quot;:&quot;[FelPersoanaCalculat]&quot;,&quot;DataDeInceput&quot;:&quot;[p_DataDeInceput]&quot;,&quot;DataDeSfarsit&quot;:&quot;[p_DataDeSfarsit]&quot;,&quot;Grad&quot;:&quot;[p_Grad]&quot;,&quot;Procent&quot;:&quot;[ProcentCalculat]&quot;,&quot;DataNasteriiCopil&quot;:&quot;[p_DataNasteriiCopil]&quot;,&quot;AltProcent&quot;:&quot;[p_AltProcent]&quot;,&quot;NumeAltaPersoana&quot;:&quot;[p_NumeAltaPersoana]&quot;,&quot;ConnectionString&quot;:null,&quot;OnError&quot;:[]}&lt;/ActionData&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
