      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;1&lt;/OrderIndex&gt;
      &lt;ActionType&gt;RunSql&lt;/ActionType&gt;
      &lt;Description&gt;Valideaza modificare persoana intretinere&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;UseTransactions&quot;:true,&quot;SqlQuery&quot;:&quot;DECLARE @DataInceputValidata DATE =\n    TRY_CONVERT(DATE, NULLIF(CONVERT(NVARCHAR(50), @DataInceput), &#39;&#39;));\n\nDECLARE @DataSfarsitValidata DATE =\n    TRY_CONVERT(DATE, NULLIF(CONVERT(NVARCHAR(50), @DataSfarsit), &#39;&#39;));\n\nDECLARE @DataNasteriiValidata DATE =\n    TRY_CONVERT(DATE, NULLIF(CONVERT(NVARCHAR(50), @DataNasterii), &#39;&#39;));\n\nDECLARE @TipPersoana INT =\n    TRY_CONVERT(INT, @FelPersoana);\n\nIF NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(450), @CodSucursala))), &#39;&#39;) IS NULL\nBEGIN\n    ;THROW 51000, &#39;Cod Sucursala este obligatoriu.&#39;, 1;\nEND;\n\nIF NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(100), @Marca))), &#39;&#39;) IS NULL\nBEGIN\n    ;THROW 51000, &#39;Marca este obligatorie.&#39;, 1;\nEND;\n\nIF NULLIF(LTRIM(RTRIM(CONVERT(NVARCHAR(100), @CNP))), &#39;&#39;) IS NULL\nBEGIN\n    ;THROW 51000, &#39;CNP persoana este obligatoriu.&#39;, 1;\nEND;\n\nIF @TipPersoana IS NULL\nBEGIN\n    ;THROW 51000, &#39;Tipul persoanei nu este valid.&#39;, 1;\nEND;\n\nIF @DataInceputValidata IS NULL\nBEGIN\n    ;THROW 51000, &#39;Data de inceput este obligatorie.&#39;, 1;\nEND;\n\nIF @DataSfarsitValidata IS NOT NULL\n   AND @DataSfarsitValidata &amp;lt; @DataInceputValidata\nBEGIN\n    ;THROW 51000, &#39;Data de sfarsit nu poate fi anterioara datei de inceput.&#39;, 1;\nEND;\n\nIF @TipPersoana IN (2, 3)\nBEGIN\n    IF @DataNasteriiValidata IS NULL\n    BEGIN\n        ;THROW 51000, &#39;Data nasterii copilului este obligatorie.&#39;, 1;\n    END;\n\n    IF @DataNasteriiValidata &amp;gt;= @DataInceputValidata\n    BEGIN\n        ;THROW 51000, &#39;Data nasterii copilului trebuie sa fie anterioara datei de inceput.&#39;, 1;\n    END;\n\n    IF DATEADD(YEAR, 18, @DataNasteriiValidata) &amp;lt;= @DataInceputValidata\n    BEGIN\n        ;THROW 51000, &#39;Copilul trebuie sa fie minor la data de inceput.&#39;, 1;\n    END;\nEND;\n\nSELECT 1 AS ValidareReusita;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[p_CodSucursala]&quot;,&quot;name&quot;:&quot;CodSucursala&quot;},{&quot;value&quot;:&quot;[p_Marca]&quot;,&quot;name&quot;:&quot;Marca&quot;},{&quot;value&quot;:&quot;[p_CNPAltaPersoana]&quot;,&quot;name&quot;:&quot;CNP&quot;},{&quot;value&quot;:&quot;[p_FelPersoana]&quot;,&quot;name&quot;:&quot;FelPersoana&quot;},{&quot;value&quot;:&quot;[p_DataDeInceput]&quot;,&quot;name&quot;:&quot;DataInceput&quot;},{&quot;value&quot;:&quot;[p_DataDeSfarsit]&quot;,&quot;name&quot;:&quot;DataSfarsit&quot;},{&quot;value&quot;:&quot;[p_DataNasteriiCopil]&quot;,&quot;name&quot;:&quot;DataNasterii&quot;}],&quot;OutputTokenName&quot;:null,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:true}&lt;/ActionData&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
    &lt;ActionInfo&gt;
      &lt;ModuleId&gt;1124&lt;/ModuleId&gt;
      &lt;FieldName&gt;Modifica&lt;/FieldName&gt;
      &lt;EventName&gt;click&lt;/EventName&gt;
      &lt;Metadata /&gt;
      &lt;OrderIndex&gt;2&lt;/OrderIndex&gt;
      &lt;ActionType&gt;RunSql&lt;/ActionType&gt;
      &lt;Description&gt;Stabileste procent la modificare&lt;/Description&gt;
      &lt;ActionData&gt;{&quot;DbConnector&quot;:{&quot;Type&quot;:&quot;Database&quot;,&quot;Group&quot;:&quot;&quot;,&quot;EntireGroup&quot;:false},&quot;ConnectionString&quot;:null,&quot;QueryTimeout&quot;:null,&quot;UseTransactions&quot;:true,&quot;SqlQuery&quot;:&quot;DECLARE @AnulCalcul INT =\n    TRY_CONVERT(INT, @Anul);\n\nDECLARE @FelNou INT =\n    TRY_CONVERT(INT, @FelPersoana);\n\nDECLARE @FelVechi INT =\n    TRY_CONVERT(INT, @FelPersoanaOriginal);\n\nDECLARE @GradNou INT =\n    TRY_CONVERT\n    (\n        INT,\n        NULLIF\n        (\n            LTRIM(RTRIM(CONVERT(NVARCHAR(50), @Grad))),\n            &#39;&#39;\n        )\n    );\n\nDECLARE @GradVechi INT =\n    TRY_CONVERT\n    (\n        INT,\n        NULLIF\n        (\n            LTRIM(RTRIM(CONVERT(NVARCHAR(50), @GradOriginal))),\n            &#39;&#39;\n        )\n    );\n\nDECLARE @ProcentVechi DECIMAL(18, 4) =\n    TRY_CONVERT\n    (\n        DECIMAL(18, 4),\n        NULLIF\n        (\n            LTRIM(RTRIM(CONVERT(NVARCHAR(50), @ProcentOriginal))),\n            &#39;&#39;\n        )\n    );\n\nIF @FelNou IS NULL\nBEGIN\n    ;THROW 51000,\n        &#39;Tipul persoanei nu este valid.&#39;,\n        1;\nEND;\n\nIF @FelNou = @FelVechi\n   AND\n   (\n       @GradNou = @GradVechi\n       OR (@GradNou IS NULL AND @GradVechi IS NULL)\n   )\n   AND @ProcentVechi IS NOT NULL\nBEGIN\n    SELECT @ProcentVechi AS ProcentCalculat;\n    RETURN;\nEND;\n\nDECLARE @NumarConfigurari INT;\nDECLARE @ProcentCalculat DECIMAL(18, 4);\n\nSELECT\n    @NumarConfigurari = COUNT(*),\n    @ProcentCalculat = MAX(Procent)\nFROM app.TipPersoana\nWHERE Anul = @AnulCalcul\n  AND FelPersoana = @FelNou\n  AND\n  (\n      Grad = @GradNou\n      OR (Grad IS NULL AND @GradNou IS NULL)\n  );\n\nIF @NumarConfigurari = 0\nBEGIN\n    ;THROW 51000,\n        &#39;Nu exista un procent configurat in Tip Persoane pentru anul, tipul si gradul selectate.&#39;,\n        1;\nEND;\n\nIF @NumarConfigurari &amp;gt; 1\nBEGIN\n    ;THROW 51000,\n        &#39;Exista configurari duplicate in Tip Persoane pentru anul, tipul si gradul selectate.&#39;,\n        1;\nEND;\n\nIF @ProcentCalculat IS NULL\nBEGIN\n    ;THROW 51000,\n        &#39;Procentul configurat in Tip Persoane este necompletat.&#39;,\n        1;\nEND;\n\nSELECT @ProcentCalculat AS ProcentCalculat;&quot;,&quot;BindTokens&quot;:[{&quot;value&quot;:&quot;[GetOrSession:YearV]&quot;,&quot;name&quot;:&quot;Anul&quot;},{&quot;value&quot;:&quot;[p_FelPersoana]&quot;,&quot;name&quot;:&quot;FelPersoana&quot;},{&quot;value&quot;:&quot;[original:FelPersoana]&quot;,&quot;name&quot;:&quot;FelPersoanaOriginal&quot;},{&quot;value&quot;:&quot;[p_Grad]&quot;,&quot;name&quot;:&quot;Grad&quot;},{&quot;value&quot;:&quot;[original:Grad]&quot;,&quot;name&quot;:&quot;GradOriginal&quot;},{&quot;value&quot;:&quot;[original:Procent]&quot;,&quot;name&quot;:&quot;ProcentOriginal&quot;}],&quot;OutputTokenName&quot;:&quot;ProcentCalculatUpdate&quot;,&quot;ExtractColumns&quot;:null,&quot;OnError&quot;:[],&quot;ShowErrors&quot;:false}&lt;/ActionData&gt;
      &lt;IsDeleted&gt;false&lt;/IsDeleted&gt;
    &lt;/ActionInfo&gt;
